$ErrorActionPreference = 'Stop'

$documents = [Environment]::GetFolderPath('MyDocuments')
if (-not $documents) { throw 'Documents folder could not be located.' }
$radar = Join-Path $documents 'radar'
New-Item -ItemType Directory -Path $radar -Force | Out-Null

$files = @{
    'radar1.m' = ''
    'radar2.m' = ''
    'radar3.m' = ''
    'radar4.m' = ''
    'radar5.m' = ''
    'radar6.m' = ''
    'radar7.m' = ''
    'radar8.m' = ''
    'radar9.m' = ''
    'radarnum1.m' = ''
}

foreach ($name in ($files.Keys | Sort-Object)) {
    $path = Join-Path $radar $name
    if (Test-Path -LiteralPath $path) {
        Write-Host "Skipped existing file: $name"
        continue
    }
    [System.IO.File]::WriteAllBytes($path, [Convert]::FromBase64String($files[$name]))
    Write-Host "Saved $name"
}

Write-Host "Radar experiments are located in: $radar"
